import torch
import triton
import triton.language as tl

# Maximum 1D grid dimension accepted by the Ascend kernel-launch API. This is a
# uniform launch limit across 910B variants (not a physical core count).
_MAX_GRID = 65535

# Lazily-cached device properties (output-independent state, not a mutable
# input): the vector-core count and L2 cache size, both queried at runtime so
# the grid is B2-portable rather than tied to any observed physical count.
_VCORES = None
_L2_BYTES = None


def _device_info():
    global _VCORES, _L2_BYTES
    if _VCORES is None:
        v = _MAX_GRID
        l2 = 0
        try:
            props = torch.npu.get_device_properties(torch.npu.current_device())
            vc = getattr(props, "vector_core_num", None)
            if vc:
                v = int(vc)
            for name in ("L2_cache_size", "l2_cache_size"):
                s = getattr(props, name, None)
                if s:
                    l2 = int(s)
                    break
        except Exception:
            pass
        _VCORES = v
        _L2_BYTES = l2
    return _VCORES, _L2_BYTES


@triton.jit
def _deg2rad_kernel(x_ptr, y_ptr, n_elements, scale, BLOCK_SIZE: tl.constexpr):
    pid = tl.program_id(0)
    num_programs = tl.num_programs(0)
    step = BLOCK_SIZE * num_programs
    for start in range(pid * BLOCK_SIZE, n_elements, step):
        offsets = start + tl.arange(0, BLOCK_SIZE)
        mask = offsets < n_elements
        x = tl.load(x_ptr + offsets, mask=mask)
        y = x.to(tl.float32) * scale
        tl.store(y_ptr + offsets, y, mask=mask)


@triton.jit
def _deg2rad_tiny_kernel(x_ptr, y_ptr, n_elements, scale, BLOCK_SIZE: tl.constexpr):
    # Single-program fast path for small tensors: the tile is narrowed to the
    # actual element count (a power of two covering n_elements) and the multiply
    # is done in the native dtype (no fp32 upcast/downcast round-trip). This
    # removes the fixed fp32-conversion and oversized-masked-tile cost that
    # dominates the 64x64=4096 timing cases.
    offsets = tl.arange(0, BLOCK_SIZE)
    mask = offsets < n_elements
    x = tl.load(x_ptr + offsets, mask=mask)
    y = x * scale.to(x.dtype)
    tl.store(y_ptr + offsets, y, mask=mask)


@triton.jit
def _deg2rad_tiny_kernel_nomask(x_ptr, y_ptr, scale, BLOCK_SIZE: tl.constexpr):
    # Exact power-of-two variant: when n_elements == BLOCK_SIZE the tile fully
    # covers the buffer, so the per-element compare and predicated load/store are
    # dropped, leaving a bare unpredicated native-dtype multiply.
    offsets = tl.arange(0, BLOCK_SIZE)
    x = tl.load(x_ptr + offsets)
    y = x * scale.to(x.dtype)
    tl.store(y_ptr + offsets, y)


def deg2rad(x):
    orig = x

    # Non-floating inputs are upcast to float32 (reference semantics).
    if x.dtype not in (torch.float16, torch.bfloat16, torch.float32, torch.float64):
        x = x.to(torch.float32)

    # Flatten to a contiguous 1D view for flat-offset addressing.
    x = x.contiguous()
    n_elements = x.numel()
    out = torch.empty_like(x)

    if n_elements == 0:
        return out.view_as(orig)

    scale = math.pi / 180.0

    # Small-tensor fast path: one program whose tile exactly covers the data.
    # When n_elements is an exact power of two the tile fully covers the buffer,
    # so a dedicated mask-free kernel drops the per-element compare/predication.
    if n_elements <= 4096:
        tiny_block = 1 << (n_elements - 1).bit_length()
        if tiny_block == n_elements:
            _deg2rad_tiny_kernel_nomask[(1,)](x, out, scale, BLOCK_SIZE=tiny_block)
        else:
            _deg2rad_tiny_kernel[(1,)](x, out, n_elements, scale, BLOCK_SIZE=tiny_block)
        return out.view_as(orig)

    BLOCK_SIZE = 16384
    num_blocks = (n_elements + BLOCK_SIZE - 1) // BLOCK_SIZE
