    # Single wave of programs for tiny/L2-resident workloads. For workloads
    # whose combined read+write footprint exceeds L2, launch a second wave
    # (2x programs) so the extra programs hide HBM latency during streaming.
    bytes_moved = n_elements * x.element_size() * 2
    if l2 > 0 and bytes_moved > l2:
        max_grid = min(2 * vcores, _MAX_GRID)
    else:
        max_grid = min(vcores, _MAX_GRID)

    grid = (min(num_blocks, max_grid),)
    _deg2rad_kernel[grid](x, out, n_elements, scale, BLOCK_SIZE=BLOCK_SIZE)

    return out.view_as(orig)
